// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.prank(caller);
        bool ok = true;
        try c.owned() { ok = true; } catch { ok = false; }
        assertTrue(ok == (caller == c.owner()));
    }
}
